round_manager_device_24 := class(creative_device):
    @editable TargetTrigger : trigger_device = trigger_device{}
    @editable ElimZone : mutator_zone_device = mutator_zone_device{}
    @editable MaxRoundTime : float = 60.0

    OnBegin<override>()<suspends> : void =
        TargetTrigger.TriggeredEvent.Subscribe(OnObjectiveTriggered)
        race:
            AwaitRoundTimeout()
            AwaitObjectiveComplete()

    AwaitRoundTimeout()<suspends> : void =
        Sleep(MaxRoundTime)
        Print("Round 24 timed out.")

    AwaitObjectiveComplete()<suspends> : void =
        loop:
            Agent := TargetTrigger.TriggeredEvent.Await()
            if (Player := player[Agent], FortChar := Player.GetFortCharacter[]):
                Print("Round 24 objective secured!")
                break

    OnObjectiveTriggered(Agent : ?agent) : void =
        if (ValidAgent := Agent?):
            Print("Agent interacted with trigger 24")

// BTTask_FindCover_18.h
#pragma once
#include "CoreMinimal.h"
#include "BehaviorTree/BTTaskNode.h"
#include "BTTask_FindCover_18.generated.h"

UCLASS()
class GAMEFORGE_API UBTTask_FindCover_18 : public UBTTaskNode
{
    GENERATED_BODY()
public:
    UBTTask_FindCover_18();
    virtual EBTNodeResult::Type ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory) override;

protected:
    UPROPERTY(EditAnywhere, Category="Blackboard")
    FBlackboardKeySelector CoverLocationKey;

    UPROPERTY(EditAnywhere, Category="Search")
    float SearchRadius = 1500.0f;
};

// BTTask_FindCover_18.cpp
#include "BTTask_FindCover_18.h"
#include "AIController.h"
#include "BehaviorTree/BlackboardComponent.h"
#include "NavigationSystem.h"

UBTTask_FindCover_18::UBTTask_FindCover_18()
{
    NodeName = "Find Cover Point 18";
    CoverLocationKey.AddVectorFilter(this, GET_MEMBER_NAME_CHECKED(UBTTask_FindCover_18, CoverLocationKey));
}

EBTNodeResult::Type UBTTask_FindCover_18::ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory)
{
    AAIController* AICon = OwnerComp.GetAIOwner();
    UBlackboardComponent* BBComp = OwnerComp.GetBlackboardComponent();
    if (!AICon || !BBComp)
    {
        return EBTNodeResult::Failed;
    }

    APawn* AIPawn = AICon->GetPawn();
    if (!AIPawn)
    {
        return EBTNodeResult::Failed;
    }

    UNavigationSystemV1* NavSys = FNavigationSystem::GetCurrent<UNavigationSystemV1>(AIPawn->GetWorld());
    if (!NavSys)
    {
        return EBTNodeResult::Failed;
    }

    FNavLocation NavLoc;
    const FVector Origin = AIPawn->GetActorLocation();
    if (NavSys->GetRandomReachablePointInRadius(Origin, SearchRadius, NavLoc))
    {
        BBComp->SetValueAsVector(CoverLocationKey.SelectedKeyName, NavLoc.Location);
        return EBTNodeResult::Succeeded;
    }

    return EBTNodeResult::Failed;
}

