use bevy::prelude::*;

#[derive(Component)]
pub struct Projectile_37 {
    pub velocity: Vec3,
    pub lifetime: Timer,
}

#[derive(Resource)]
pub struct CombatConfig_37 {
    pub base_speed: f32,
    pub max_lifetime: f32,
}

pub struct CombatPlugin_37;

impl Plugin for CombatPlugin_37 {
    fn build(&self, app: &mut App) {
        app.insert_resource(CombatConfig_37 {
            base_speed: 45.0,
            max_lifetime: 3.5,
        })
        .add_systems(Update, (update_projectiles_37, cleanup_expired_projectiles_37));
    }
}

fn update_projectiles_37(
    time: Res<Time>,
    mut query: Query<(&mut Transform, &mut Projectile_37)>,
) {
    for (mut transform, mut proj) in query.iter_mut() {
        proj.lifetime.tick(time.delta());
        transform.translation += proj.velocity * time.delta_seconds();
    }
}

fn cleanup_expired_projectiles_37(
    mut commands: Commands,
    query: Query<(Entity, &Projectile_37)>,
) {
    for (entity, proj) in query.iter() {
        if proj.lifetime.finished() {
            commands.entity(entity).despawn_recursive();
        }
    }
}

