pub struct CombatPlugin_9;

impl Plugin for CombatPlugin_9 {
    fn build(&self, app: &mut App) {
        app.insert_resource(CombatConfig_9 {
            base_speed: 45.0,
            max_lifetime: 3.5,
        })
        .add_systems(Update, (update_projectiles_9, cleanup_expired_projectiles_9));
    }
}

fn update_projectiles_9(
    time: Res<Time>,
    mut query: Query<(&mut Transform, &mut Projectile_9)>,
) {
    for (mut transform, mut proj) in query.iter_mut() {
        proj.lifetime.tick(time.delta());
        transform.translation += proj.velocity * time.delta_seconds();
    }
}

fn cleanup_expired_projectiles_9(
    mut commands: Commands,
    query: Query<(Entity, &Projectile_9)>,
) {
    for (entity, proj) in query.iter() {
        if proj.lifetime.finished() {
            commands.entity(entity).despawn_recursive();
        }
    }
}

