class_name AdvancedCharacterController_36
extends CharacterBody3D

@export var move_speed: float = 6.5
@export var jump_velocity: float = 4.8
@export var acceleration: float = 12.0
@export var friction: float = 10.0
@export var coyote_duration: float = 0.15
@export var jump_buffer_duration: float = 0.12

var gravity: float = ProjectSettings.get_setting("physics/3d/default_gravity")
var coyote_timer: float = 0.0
var jump_buffer_timer: float = 0.0

@onready var camera_pivot: Node3D = $CameraPivot

func _physics_process(delta: float) -> void:
    # Update Timers
    if is_on_floor():
        coyote_timer = coyote_duration
    else:
        coyote_timer = maxf(0.0, coyote_timer - delta)
        velocity.y -= gravity * delta

    if Input.is_action_just_pressed("jump"):
        jump_buffer_timer = jump_buffer_duration
    else:
        jump_buffer_timer = maxf(0.0, jump_buffer_timer - delta)

    # Execute Jump
    if jump_buffer_timer > 0.0 and coyote_timer > 0.0:
        velocity.y = jump_velocity
        jump_buffer_timer = 0.0
        coyote_timer = 0.0

    # Horizontal Movement
    var input_dir: Vector2 = Input.get_vector("move_left", "move_right", "move_forward", "move_backward")
    var direction: Vector3 = (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()

    if direction.length_squared() > 0.001:
        velocity.x = move_toward(velocity.x, direction.x * move_speed, acceleration * delta)
        velocity.z = move_toward(velocity.z, direction.z * move_speed, acceleration * delta)
    else:
        velocity.x = move_toward(velocity.x, 0.0, friction * delta)
        velocity.z = move_toward(velocity.z, 0.0, friction * delta)

    move_and_slide()

// ProjectileSweep_10.h
#pragma once
#include "CoreMinimal.h"
#include "Kismet/BlueprintFunctionLibrary.h"
#include "Engine/HitResult.h"
#include "ProjectileSweep_10.generated.h"

UCLASS()
class GAMEFORGE_API UProjectileSweepLibrary_10 : public UBlueprintFunctionLibrary
{
    GENERATED_BODY()
public:
    UFUNCTION(BlueprintCallable, Category="GameForge|Collision")
    static bool PerformPenetratingCapsuleSweep(
        UObject* WorldContextObject,
        const FVector& Start,
        const FVector& End,
        float Radius,
        float HalfHeight,
        ECollisionChannel Channel,
        const TArray<AActor*>& IgnoredActors,
        TArray<FHitResult>& OutHits
    );
};

// ProjectileSweep_10.cpp
#include "ProjectileSweep_10.h"
#include "Engine/World.h"
#include "CollisionQueryParams.h"

bool UProjectileSweepLibrary_10::PerformPenetratingCapsuleSweep(
    UObject* WorldContextObject,
    const FVector& Start,
    const FVector& End,
    float Radius,
    float HalfHeight,
    ECollisionChannel Channel,
    const TArray<AActor*>& IgnoredActors,
    TArray<FHitResult>& OutHits
)
{
    if (!WorldContextObject) return false;
    UWorld* World = WorldContextObject->GetWorld();
    if (!World) return false;

    FCollisionShape CapsuleShape = FCollisionShape::MakeCapsule(Radius, HalfHeight);
    FCollisionQueryParams Params(SCENE_QUERY_STAT(PenetratingCapsuleSweep_10), false);
    Params.bReturnPhysicalMaterial = true;
    Params.AddIgnoredActors(IgnoredActors);

    return World->SweepMultiByChannel(
        OutHits,
        Start,
        End,
        FQuat::Identity,
        Channel,
        CapsuleShape,
        Params
    );
}

