use bevy::prelude::*;

#[derive(Component)]
pub struct Projectile_30 {
    pub velocity: Vec3,
    pub lifetime: Timer,
}

#[derive(Resource)]
pub struct CombatConfig_30 {
    pub base_speed: f32,
    pub max_lifetime: f32,
}

pub struct CombatPlugin_30;

impl Plugin for CombatPlugin_30 {
    fn build(&self, app: &mut App) {
        app.insert_resource(CombatConfig_30 {
            base_speed: 45.0,
            max_lifetime: 3.5,
        })
        .add_systems(Update, (update_projectiles_30, cleanup_expired_projectiles_30));
    }
}

fn update_projectiles_30(
    time: Res<Time>,
    mut query: Query<(&mut Transform, &mut Projectile_30)>,
) {
    for (mut transform, mut proj) in query.iter_mut() {
        proj.lifetime.tick(time.delta());
        transform.translation += proj.velocity * time.delta_seconds();
    }
}

fn cleanup_expired_projectiles_30(
    mut commands: Commands,
    query: Query<(Entity, &Projectile_30)>,
) {
    for (entity, proj) in query.iter() {
        if proj.lifetime.finished() {
            commands.entity(entity).despawn_recursive();
        }
    }
}

