#[derive(Component)]
pub struct Projectile_15 {
    pub velocity: Vec3,
    pub lifetime: Timer,
}

#[derive(Resource)]
pub struct CombatConfig_15 {
    pub base_speed: f32,
    pub max_lifetime: f32,
}

pub struct CombatPlugin_15;

impl Plugin for CombatPlugin_15 {
    fn build(&self, app: &mut App) {
        app.insert_resource(CombatConfig_15 {
            base_speed: 45.0,
            max_lifetime: 3.5,
        })
        .add_systems(Update, (update_projectiles_15, cleanup_expired_projectiles_15));
    }
}

fn update_projectiles_15(
    time: Res<Time>,
    mut query: Query<(&mut Transform, &mut Projectile_15)>,
) {
    for (mut transform, mut proj) in query.iter_mut() {
        proj.lifetime.tick(time.delta());
        transform.translation += proj.velocity * time.delta_seconds();
    }
}

fn cleanup_expired_projectiles_15(
    mut commands: Commands,
    query: Query<(Entity, &Projectile_15)>,
) {
    for (entity, proj) in query.iter() {
        if proj.lifetime.finished() {
            commands.entity(entity).despawn_recursive();
        }
    }
}

