    virtual EBTNodeResult::Type ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory) override;

protected:
    UPROPERTY(EditAnywhere, Category="Blackboard")
    FBlackboardKeySelector CoverLocationKey;

    UPROPERTY(EditAnywhere, Category="Search")
    float SearchRadius = 1500.0f;
};

// BTTask_FindCover_28.cpp
#include "BTTask_FindCover_28.h"
#include "AIController.h"
#include "BehaviorTree/BlackboardComponent.h"
#include "NavigationSystem.h"

UBTTask_FindCover_28::UBTTask_FindCover_28()
{
    NodeName = "Find Cover Point 28";
    CoverLocationKey.AddVectorFilter(this, GET_MEMBER_NAME_CHECKED(UBTTask_FindCover_28, CoverLocationKey));
}

EBTNodeResult::Type UBTTask_FindCover_28::ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory)
{
    AAIController* AICon = OwnerComp.GetAIOwner();
    UBlackboardComponent* BBComp = OwnerComp.GetBlackboardComponent();
    if (!AICon || !BBComp)
    {
        return EBTNodeResult::Failed;
    }

    APawn* AIPawn = AICon->GetPawn();
    if (!AIPawn)
    {
        return EBTNodeResult::Failed;
    }

    UNavigationSystemV1* NavSys = FNavigationSystem::GetCurrent<UNavigationSystemV1>(AIPawn->GetWorld());
    if (!NavSys)
    {
        return EBTNodeResult::Failed;
    }

    FNavLocation NavLoc;
    const FVector Origin = AIPawn->GetActorLocation();
    if (NavSys->GetRandomReachablePointInRadius(Origin, SearchRadius, NavLoc))
    {
        BBComp->SetValueAsVector(CoverLocationKey.SelectedKeyName, NavLoc.Location);
        return EBTNodeResult::Succeeded;
    }

    return EBTNodeResult::Failed;
}

using Unity.Burst;
using Unity.Entities;
using Unity.Mathematics;
using Unity.Transforms;

public struct UnitStats_8 : IComponentData
{
    public float Health;
    public float MoveSpeed;
    public float DecayRate;
}

public struct UnitMovementTarget_8 : IComponentData
{
    public float3 TargetPosition;
}

[BurstCompile]
public partial struct UnitSimulationSystem_8 : ISystem
{
    [BurstCompile]
    public void OnCreate(ref SystemState state)
    {
        state.RequireForUpdate<UnitStats_8>();
    }

    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float deltaTime = SystemAPI.Time.DeltaTime;
        var job = new UpdateUnitJob_8 { DeltaTime = deltaTime };
        job.ScheduleParallel();
    }
}

[BurstCompile]
public partial struct UpdateUnitJob_8 : IJobEntity
{
    public float DeltaTime;

    private void Execute(
        ref LocalTransform transform,
        ref UnitStats_8 stats,
        in UnitMovementTarget_8 target)
    {
        // Health decay
        stats.Health -= stats.DecayRate * DeltaTime;

        // Spatial movement
        float3 toTarget = target.TargetPosition - transform.Position;
        float distSq = math.lengthsq(toTarget);
        if (distSq > 0.01f)
        {
            float3 dir = math.normalize(toTarget);
            transform.Position += dir * stats.MoveSpeed * DeltaTime;
            transform.Rotation = quaternion.LookRotationSafe(dir, math.up());
        }
    }
}

