[BurstCompile]
public partial struct UnitSimulationSystem_39 : ISystem
{
    [BurstCompile]
    public void OnCreate(ref SystemState state)
    {
        state.RequireForUpdate<UnitStats_39>();
    }

    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float deltaTime = SystemAPI.Time.DeltaTime;
        var job = new UpdateUnitJob_39 { DeltaTime = deltaTime };
        job.ScheduleParallel();
    }
