using Unity.Burst;
using Unity.Entities;
using Unity.Mathematics;
using Unity.Transforms;

public struct UnitStats_35 : IComponentData
{
    public float Health;
    public float MoveSpeed;
    public float DecayRate;
}

public struct UnitMovementTarget_35 : IComponentData
{
    public float3 TargetPosition;
}

[BurstCompile]
public partial struct UnitSimulationSystem_35 : ISystem
{
    [BurstCompile]
    public void OnCreate(ref SystemState state)
    {
        state.RequireForUpdate<UnitStats_35>();
    }

    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float deltaTime = SystemAPI.Time.DeltaTime;
        var job = new UpdateUnitJob_35 { DeltaTime = deltaTime };
        job.ScheduleParallel();
    }
}

[BurstCompile]
public partial struct UpdateUnitJob_35 : IJobEntity
{
    public float DeltaTime;

    private void Execute(
        ref LocalTransform transform,
        ref UnitStats_35 stats,
        in UnitMovementTarget_35 target)
    {
        // Health decay
        stats.Health -= stats.DecayRate * DeltaTime;

        // Spatial movement
        float3 toTarget = target.TargetPosition - transform.Position;
        float distSq = math.lengthsq(toTarget);
        if (distSq > 0.01f)
        {
            float3 dir = math.normalize(toTarget);
            transform.Position += dir * stats.MoveSpeed * DeltaTime;
            transform.Rotation = quaternion.LookRotationSafe(dir, math.up());
        }
    }
}

use bevy::prelude::*;

#[derive(Component)]
pub struct Projectile_38 {
    pub velocity: Vec3,
    pub lifetime: Timer,
}

#[derive(Resource)]
pub struct CombatConfig_38 {
    pub base_speed: f32,
    pub max_lifetime: f32,
}

pub struct CombatPlugin_38;

impl Plugin for CombatPlugin_38 {
    fn build(&self, app: &mut App) {
        app.insert_resource(CombatConfig_38 {
            base_speed: 45.0,
            max_lifetime: 3.5,
        })
        .add_systems(Update, (update_projectiles_38, cleanup_expired_projectiles_38));
    }
}

fn update_projectiles_38(
    time: Res<Time>,
    mut query: Query<(&mut Transform, &mut Projectile_38)>,
) {
    for (mut transform, mut proj) in query.iter_mut() {
        proj.lifetime.tick(time.delta());
        transform.translation += proj.velocity * time.delta_seconds();
    }
}

fn cleanup_expired_projectiles_38(
    mut commands: Commands,
    query: Query<(Entity, &Projectile_38)>,
) {
    for (entity, proj) in query.iter() {
        if proj.lifetime.finished() {
            commands.entity(entity).despawn_recursive();
        }
    }
}

