    virtual EBTNodeResult::Type ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory) override;

protected:
    UPROPERTY(EditAnywhere, Category="Blackboard")
    FBlackboardKeySelector CoverLocationKey;

    UPROPERTY(EditAnywhere, Category="Search")
    float SearchRadius = 1500.0f;
};

// BTTask_FindCover_26.cpp
#include "BTTask_FindCover_26.h"
#include "AIController.h"
#include "BehaviorTree/BlackboardComponent.h"
#include "NavigationSystem.h"

UBTTask_FindCover_26::UBTTask_FindCover_26()
{
    NodeName = "Find Cover Point 26";
    CoverLocationKey.AddVectorFilter(this, GET_MEMBER_NAME_CHECKED(UBTTask_FindCover_26, CoverLocationKey));
}

EBTNodeResult::Type UBTTask_FindCover_26::ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory)
{
    AAIController* AICon = OwnerComp.GetAIOwner();
    UBlackboardComponent* BBComp = OwnerComp.GetBlackboardComponent();
    if (!AICon || !BBComp)
    {
        return EBTNodeResult::Failed;
    }

    APawn* AIPawn = AICon->GetPawn();
    if (!AIPawn)
    {
        return EBTNodeResult::Failed;
    }

    UNavigationSystemV1* NavSys = FNavigationSystem::GetCurrent<UNavigationSystemV1>(AIPawn->GetWorld());
    if (!NavSys)
    {
        return EBTNodeResult::Failed;
    }

    FNavLocation NavLoc;
    const FVector Origin = AIPawn->GetActorLocation();
    if (NavSys->GetRandomReachablePointInRadius(Origin, SearchRadius, NavLoc))
    {
        BBComp->SetValueAsVector(CoverLocationKey.SelectedKeyName, NavLoc.Location);
        return EBTNodeResult::Succeeded;
    }

    return EBTNodeResult::Failed;
}

class_name AdvancedCharacterController_32
extends CharacterBody3D

@export var move_speed: float = 6.5
@export var jump_velocity: float = 4.8
@export var acceleration: float = 12.0
@export var friction: float = 10.0
@export var coyote_duration: float = 0.15
@export var jump_buffer_duration: float = 0.12

var gravity: float = ProjectSettings.get_setting("physics/3d/default_gravity")
var coyote_timer: float = 0.0
var jump_buffer_timer: float = 0.0

@onready var camera_pivot: Node3D = $CameraPivot

func _physics_process(delta: float) -> void:
    # Update Timers
    if is_on_floor():
        coyote_timer = coyote_duration
    else:
        coyote_timer = maxf(0.0, coyote_timer - delta)
        velocity.y -= gravity * delta

    if Input.is_action_just_pressed("jump"):
        jump_buffer_timer = jump_buffer_duration
    else:
        jump_buffer_timer = maxf(0.0, jump_buffer_timer - delta)

    # Execute Jump
    if jump_buffer_timer > 0.0 and coyote_timer > 0.0:
        velocity.y = jump_velocity
        jump_buffer_timer = 0.0
        coyote_timer = 0.0

    # Horizontal Movement
    var input_dir: Vector2 = Input.get_vector("move_left", "move_right", "move_forward", "move_backward")
    var direction: Vector3 = (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()

    if direction.length_squared() > 0.001:
        velocity.x = move_toward(velocity.x, direction.x * move_speed, acceleration * delta)
        velocity.z = move_toward(velocity.z, direction.z * move_speed, acceleration * delta)
    else:
        velocity.x = move_toward(velocity.x, 0.0, friction * delta)
        velocity.z = move_toward(velocity.z, 0.0, friction * delta)

    move_and_slide()

